CREATE TABLE IF NOT EXISTS rm_workspace_document_access_events (
 id INTEGER PRIMARY KEY,
 actor TEXT NOT NULL CHECK(length(actor) BETWEEN 6 AND 160 AND substr(actor, 1, 5) = 'user:' AND substr(actor, 6) NOT GLOB '*[^A-Za-z0-9._-]*'),
 company_slug TEXT NOT NULL CHECK(length(company_slug) BETWEEN 1 AND 120 AND substr(company_slug, 1, 1) GLOB '[a-z0-9]' AND company_slug NOT GLOB '*[^a-z0-9-]*'),
 resource_type TEXT NOT NULL CHECK(resource_type IN ('document_file','issued_invoice_pdf')),
 resource_id INTEGER CHECK(resource_id IS NULL OR resource_id > 0),
 outcome TEXT NOT NULL CHECK(outcome IN ('served','denied')),
 reason_code TEXT NOT NULL CHECK(reason_code IN ('authorized','authorization_denied')),
 request_id TEXT CHECK(request_id IS NULL OR (length(request_id) BETWEEN 1 AND 64 AND substr(request_id, 1, 1) GLOB '[A-Za-z0-9]' AND request_id NOT GLOB '*[^A-Za-z0-9._-]*')),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS rm_workspace_document_access_events_lookup ON rm_workspace_document_access_events(company_slug, resource_type, resource_id, id DESC);
CREATE TRIGGER IF NOT EXISTS rm_workspace_document_access_events_no_update BEFORE UPDATE ON rm_workspace_document_access_events BEGIN SELECT RAISE(ABORT, 'workspace document access events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS rm_workspace_document_access_events_no_delete BEFORE DELETE ON rm_workspace_document_access_events BEGIN SELECT RAISE(ABORT, 'workspace document access events are append-only'); END;
